function normalized(a){var f=a.find(v=>v!=null);return f?a.map(v=>v==null?null:(v-f)/f*100):a}
function chart(a,b){var all=[...a,...b].filter(v=>v!=null);if(!all.length)return'';var min=Math.min(...all),max=Math.max(...all),pad=Math.max((max-min)*.12,1);min-=pad;max+=pad;var L=48,R=748,T=14,B=168;function xy(x){return x.map((v,i)=>v==null?null:[L+(i/Math.max(x.length-1,1))*(R-L),B-((v-min)/(max-min))*(B-T)]).filter(Boolean)}function pts(x){return xy(x).map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}var pa=xy(a),area=pa.length?'M '+pa[0][0]+' '+B+' L '+pa.map(p=>p[0]+' '+p[1]).join(' L ')+' L '+pa[pa.length-1][0]+' '+B+' Z':'';var ticks=[0,.25,.5,.75,1];return '<div class="mi-chart-stage"><svg viewBox="0 0 760 190" preserveAspectRatio="none" role="img" aria-label="Rendimiento del portafolio comparado con S&P 500"><defs><linearGradient id="miPfGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#22d3ee" stop-opacity=".22"/><stop offset="1" stop-color="#22d3ee" stop-opacity="0"/></linearGradient></defs>'+ticks.map(t=>{var y=T+t*(B-T),v=max-t*(max-min);return '<line x1="'+L+'" x2="'+R+'" y1="'+y+'" y2="'+y+'" class="mi-chart-line"/><text x="'+(L-8)+'" y="'+(y+3)+'" class="mi-chart-axis">'+(v>=0?'+':'')+v.toFixed(1)+'%</text>'}).join('')+(min<0&&max>0?'<line x1="'+L+'" x2="'+R+'" y1="'+(B-((0-min)/(max-min))*(B-T))+'" y2="'+(B-((0-min)/(max-min))*(B-T))+'" class="mi-chart-zero"/>':'')+'<path d="'+area+'" fill="url(#miPfGradient)"/><polyline points="'+pts(a)+'" fill="none" stroke="#22d3ee" stroke-width="2.5" vector-effect="non-scaling-stroke"/><polyline points="'+pts(b)+'" fill="none" stroke="#9b87f5" stroke-width="1.8" stroke-dasharray="7 6" vector-effect="non-scaling-stroke"/><line class="mi-chart-cursor" x1="0" x2="0" y1="'+T+'" y2="'+B+'" hidden/><circle class="mi-chart-point" cx="0" cy="0" r="4" hidden/></svg><div class="mi-chart-tip" hidden></div></div>'}
function chartStats(values){var v=values.filter(x=>x!=null&&isFinite(x));if(!v.length)return'';var last=v[v.length-1],max=Math.max(...v),min=Math.min(...v);return '<div class="mi-chart-summary"><span>Último<b class="'+(last>=0?'up':'down')+'">'+pct(last)+'</b></span><span>Máximo<b class="up">'+pct(max)+'</b></span><span>Mínimo<b class="down">'+pct(min)+'</b></span><span>Observaciones<b>'+v.length+'</b></span></div>'}
