function openTicker(t){t=String(t||'').trim().toUpperCase();if(!/^[A-Z0-9.^=-]{1,15}$/.test(t)){toast('Ticker inválido');return}go('screener');setTimeout(()=>{var i=$('#ticker-input');if(i)i.value=t;if(window.fetchStock)fetchStock()},80)}
