function chartTheme(){if(typeof window.Chart==='undefined')return;Chart.defaults.color='#748196';Chart.defaults.font.family="'IBM Plex Mono', monospace";Chart.defaults.font.size=10;Chart.defaults.animation.duration=window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:420;Chart.defaults.interaction.mode='index';Chart.defaults.interaction.intersect=false;Chart.defaults.plugins.legend.labels.usePointStyle=true;Chart.defaults.plugins.legend.labels.pointStyle='line';Chart.defaults.plugins.legend.labels.boxWidth=22;Chart.defaults.plugins.legend.labels.padding=16;Chart.defaults.plugins.tooltip.backgroundColor='rgba(9,15,22,.96)';Chart.defaults.plugins.tooltip.titleColor='#f8fbff';Chart.defaults.plugins.tooltip.bodyColor='#a7b3c5';Chart.defaults.plugins.tooltip.borderColor='rgba(148,163,184,.2)';Chart.defaults.plugins.tooltip.borderWidth=1;Chart.defaults.plugins.tooltip.padding=11;Chart.defaults.plugins.tooltip.cornerRadius=8;Chart.defaults.elements.line.borderWidth=2;Chart.defaults.elements.line.tension=.28;Chart.defaults.elements.point.radius=0;Chart.defaults.elements.point.hoverRadius=4;var plugin={id:'miCrosshair',afterDraw:function(c){var a=c.tooltip&&c.tooltip.getActiveElements&&c.tooltip.getActiveElements();if(!a||!a.length||!c.chartArea)return;var x=a[0].element.x,ctx=c.ctx;ctx.save();ctx.beginPath();ctx.moveTo(x,c.chartArea.top);ctx.lineTo(x,c.chartArea.bottom);ctx.lineWidth=1;ctx.strokeStyle='rgba(148,163,184,.3)';ctx.setLineDash([3,4]);ctx.stroke();ctx.restore()}};try{Chart.register(plugin)}catch(e){}}
