function focusControls(){var set=new Set($$('.chart-wrap,.mi-chart-card,#tv-chart-section,.mi-widget.mi-portfolio'));['chart-historical','chart-portfolio','chart-market-perf'].forEach(id=>{var c=$('#'+id);if(c)set.add(c.closest('.card,.chart-wrap,.mi-chart-card')||c.parentElement)});set.forEach(host=>{if(!host||$('.mi-focus-button',host))return;host.classList.add('mi-focusable');var title=host.dataset.focusTitle||(($('.chart-title,.mi-chart-heading,h2',host)||{}).textContent||'Panel').trim();var b=document.createElement('button');b.type='button';b.className='mi-icon mi-focus-button';b.innerHTML=ico('expand',16);b.title='Abrir modo enfoque';b.setAttribute('aria-label','Abrir '+title+' en modo enfoque');b.onclick=e=>{e.stopPropagation();focusHost===host?exitFocus():enterFocus(host)};host.appendChild(b)})}
function registerExtremaPlugin(){if(typeof window.Chart==='undefined'||window.__miExtremaPlugin)return;window.__miExtremaPlugin=true;try{Chart.register({id:'miExtrema',afterDatasetsDraw:function(c){if(c.width<520||!c.chartArea)return;var meta=c.getDatasetMeta(0),ds=c.data&&c.data.datasets&&c.data.datasets[0];if(!meta||meta.hidden||!ds||!Array.isArray(ds.data)||ds.data.length<5)return;var values=ds.data.map((v,i)=>({i:i,v:Number(v&&typeof v==='object'?(v.y!=null?v.y:v.close):v)})).filter(x=>isFinite(x.v)&&meta.data[x.i]);if(values.length<5)return;var max=values.reduce((a,b)=>b.v>a.v?b:a),min=values.reduce((a,b)=>b.v<a.v?b:a),last=values[values.length-1],marks=[{p:max,t:'Máx',c:'#34d399'},{p:min,t:'Mín',c:'#fb7185'},{p:last,t:'Últ.',c:'#22d3ee'}],seen=new Set(),ctx=c.ctx;ctx.save();ctx.font="600 8px 'IBM Plex Mono', monospace";marks.forEach(m=>{if(seen.has(m.p.i))return;seen.add(m.p.i);var point=meta.data[m.p.i],x=Math.max(c.chartArea.left+18,Math.min(c.chartArea.right-18,point.x)),y=Math.max(c.chartArea.top+10,Math.min(c.chartArea.bottom-8,point.y));ctx.beginPath();ctx.arc(point.x,point.y,3.2,0,Math.PI*2);ctx.fillStyle=m.c;ctx.fill();ctx.fillText(m.t,x-10,y-7)});ctx.restore()}})}catch(e){}}
